import catalogJson from "./atlas-catalog.json";

/**
 * Runtime access to the curriculum atlas (agent-jobs plan §A3). The atlas
 * is 155 hand-researched, vetted curriculum profiles, global reference
 * data with no tenancy: it never varies by family and holds nothing
 * private, so it is bundled into the app rather than kept in Postgres
 * (BUILD.md law #2 reserves Postgres for family-scoped durable state).
 *
 * atlas-catalog.json is generated by scripts/curriculum-atlas-index.mts
 * alongside the docs copy, so the two never drift. find_curriculum_profile
 * reads this to ground a curriculum build in vetted data before ever
 * touching a live page (no cost, no injection surface).
 */

export interface CurriculumProfile {
  id: string;
  name: string;
  publisher: string;
  category: string;
  subjects: string[];
  grade_range: string;
  approach_tags: string[];
  religious_orientation: string;
  religious_notes?: string;
  format: string[];
  parent_involvement: string;
  mastery_or_spiral: string;
  price_band: string;
  price_notes?: string;
  homa_tier: string;
  status: string;
  official_site?: string;
  sources?: string[];
}

interface Catalog {
  profile_count: number;
  by_category: Record<string, number>;
  by_tier: Record<string, number>;
  profiles: CurriculumProfile[];
}

const catalog = catalogJson as unknown as Catalog;

export const CURRICULUM_CATEGORIES = Object.keys(catalog.by_category);

export interface CurriculumQuery {
  /** Free text matched against id, name, and publisher. */
  text?: string;
  id?: string;
  category?: string;
  subjects?: string[];
  approachTags?: string[];
  religiousOrientation?: string;
  limit?: number;
}

/** The fields worth returning to ground a build. Excludes repo-internal
 * bookkeeping (path, lines, last_reviewed). */
function toSummary(p: CurriculumProfile) {
  return {
    id: p.id,
    name: p.name,
    publisher: p.publisher,
    category: p.category,
    subjects: p.subjects,
    gradeRange: p.grade_range,
    approachTags: p.approach_tags,
    religiousOrientation: p.religious_orientation,
    religiousNotes: p.religious_notes ?? null,
    format: p.format,
    parentInvolvement: p.parent_involvement,
    masteryOrSpiral: p.mastery_or_spiral,
    priceBand: p.price_band,
    priceNotes: p.price_notes ?? null,
    tier: p.homa_tier,
    officialSite: p.official_site ?? null,
    sources: p.sources ?? [],
  };
}

export type CurriculumProfileSummary = ReturnType<typeof toSummary>;

function normalize(value: string): string {
  return value.toLowerCase().trim();
}

/**
 * Find atlas profiles for a query. An exact id match returns just that
 * profile. Otherwise filters by the given facets and ranks a free-text
 * match (exact name, then name/publisher substring, then id substring).
 */
export function findCurriculumProfiles(
  query: CurriculumQuery,
): CurriculumProfileSummary[] {
  const limit = Math.max(1, Math.min(query.limit ?? 5, 25));

  if (query.id) {
    const wanted = normalize(query.id);
    const exact = catalog.profiles.find((p) => normalize(p.id) === wanted);
    return exact ? [toSummary(exact)] : [];
  }

  const text = query.text ? normalize(query.text) : null;
  const category = query.category ? normalize(query.category) : null;
  const wantSubjects = (query.subjects ?? []).map(normalize);
  const wantTags = (query.approachTags ?? []).map(normalize);
  const religion = query.religiousOrientation ? normalize(query.religiousOrientation) : null;

  const scored: { profile: CurriculumProfile; score: number }[] = [];
  for (const p of catalog.profiles) {
    if (category && normalize(p.category) !== category) continue;
    if (religion && normalize(p.religious_orientation) !== religion) continue;
    if (
      wantSubjects.length > 0 &&
      !wantSubjects.every((s) => p.subjects.map(normalize).includes(s))
    ) {
      continue;
    }
    if (
      wantTags.length > 0 &&
      !wantTags.every((t) => p.approach_tags.map(normalize).includes(t))
    ) {
      continue;
    }

    let score = 1;
    if (text) {
      const name = normalize(p.name);
      const publisher = normalize(p.publisher);
      const id = normalize(p.id);
      if (name === text) score = 100;
      else if (name.includes(text) || text.includes(name)) score = 60;
      else if (publisher.includes(text)) score = 40;
      else if (id.includes(text)) score = 30;
      else continue;
    }
    scored.push({ profile: p, score });
  }

  scored.sort((a, b) => b.score - a.score || a.profile.name.localeCompare(b.profile.name));
  return scored.slice(0, limit).map((s) => toSummary(s.profile));
}
